// Frozen fictional profile generated by the four-question release flow; compatibility fixture for post-profile tests.
const profile=require('../fixtures/starting-profile-v1.json').completed;
const completed=()=>JSON.parse(JSON.stringify(profile));
function ready(s){s.startingProfile=completed();return s;}
async function browser(page){await page.context().addInitScript(p=>window.FictionalStartingProfile=p,completed());}
module.exports={completed,ready,browser};
